//! Interop with today's TypeScript peer code, run in a child `node` process
//! (ts/peer-node.ts → infra/src/peer/{x509,secure-channel}.ts). Every identity
//! is generated by the TypeScript generator at test time, with invented names.
//!
//! Needs `node` (≥ 22.18, runs .ts directly) on PATH.

use std::{path::PathBuf, process::Stdio, time::Duration};

use bytes::Bytes;
use http::{Method, Response};
use serde_json::Value;
use spike_peer::{
    goaway::{self, GoAwayTap},
    h2util::{self, read_all, send_all},
    identity::Identity,
    link::{accept_secure, connect_secure},
    pin::SignatureCheck,
    pipe::H2Pipe,
};
use tokio::{
    io::{AsyncBufReadExt, BufReader, Lines},
    net::{TcpListener, TcpStream},
    process::{Child, ChildStdout, Command},
    time::timeout,
};

const WAIT: Duration = Duration::from_secs(20);

fn spike_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("..")
}

struct Node {
    _child: Child,
    lines: Lines<BufReader<ChildStdout>>,
}

impl Node {
    fn spawn(args: &[&str]) -> Self {
        let mut child = Command::new("node")
            .arg("ts/peer-node.ts")
            .args(args)
            .current_dir(spike_root())
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .kill_on_drop(true)
            .spawn()
            .expect("node on PATH");
        let lines = BufReader::new(child.stdout.take().expect("stdout")).lines();
        Self { _child: child, lines }
    }

    async fn next(&mut self) -> Value {
        let line =
            timeout(WAIT, self.lines.next_line()).await.expect("node answered in time").expect("read").expect("a line");
        serde_json::from_str(&line).expect("json line")
    }
}

/// A fresh identity from the TypeScript generator.
async fn ts_identity(dir: &tempfile::TempDir, name: &str) -> (PathBuf, Identity) {
    let path = dir.path().join(name);
    let mut node = Node::spawn(&["gen", path.to_str().unwrap(), "eos-device"]);
    let said = node.next().await;
    let id = Identity::load(&path).expect("identity loads");
    assert_eq!(id.fingerprint, said["fingerprint"].as_str().unwrap(), "fingerprint = sha256(cert DER)");
    (path, id)
}

fn body_json(bytes: &[u8]) -> Value {
    serde_json::from_slice(bytes).expect("json body")
}

// ---- spike 2: the identity under rustls ------------------------------------------------

#[tokio::test]
async fn the_ts_certificate_parses_and_webpki_accepts_it_for_signature_checks() {
    let dir = tempfile::tempdir().unwrap();
    let (_, id) = ts_identity(&dir, "a").await;

    let (_, cert) = x509_parser::parse_x509_certificate(&id.cert).expect("x509-parser reads it");
    assert_eq!(cert.version().0, 2, "v3");
    assert_eq!(cert.extensions().len(), 0, "no extensions at all");
    assert_eq!(cert.validity().not_after.to_datetime().year(), 9999);
    assert_eq!(cert.subject().to_string(), "CN=eos-device");
    assert!(cert.raw_serial().len() <= 17);

    // The exact call rustls makes before it verifies a handshake signature.
    webpki::EndEntityCert::try_from(&id.cert).expect("webpki parses the hand-built certificate");
}

/// The serial is 16 random bytes: a leading zero is stripped, a high bit gets a
/// zero in front. Many certificates cover every length the generator can write.
#[tokio::test]
async fn webpki_accepts_every_serial_shape_the_generator_writes() {
    let mut node = Node::spawn(&["certs", "400"]);
    let mut serial_lengths = std::collections::BTreeSet::new();
    for _ in 0..400 {
        let said = node.next().await;
        let der = base64_decode(said["der"].as_str().unwrap());
        assert_eq!(spike_peer::identity::fingerprint(&der), said["fingerprint"].as_str().unwrap());
        let cert = rustls::pki_types::CertificateDer::from(der.as_slice());
        webpki::EndEntityCert::try_from(&cert).expect("webpki parses it");
        let (_, parsed) = x509_parser::parse_x509_certificate(&der).expect("x509-parser parses it");
        serial_lengths.insert(parsed.raw_serial().len());
    }
    assert!(serial_lengths.contains(&16) && serial_lengths.contains(&17), "{serial_lengths:?}");
}

fn base64_decode(text: &str) -> Vec<u8> {
    const ALPHABET: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = Vec::new();
    let (mut acc, mut bits) = (0u32, 0u32);
    for c in text.bytes().filter(|c| *c != b'=') {
        acc = (acc << 6) | ALPHABET.iter().position(|a| *a == c).expect("base64") as u32;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push((acc >> bits) as u8);
        }
    }
    out
}

#[tokio::test]
async fn rust_to_rust_handshake_on_ts_identities_with_both_signature_checks() {
    let dir = tempfile::tempdir().unwrap();
    let (_, host) = ts_identity(&dir, "host").await;
    let (_, device) = ts_identity(&dir, "device").await;
    for how in [SignatureCheck::Webpki, SignatureCheck::RawSpki] {
        let (a, b) = tokio::io::duplex(64 * 1024);
        let (client, server) =
            tokio::join!(connect_secure(a, &device, &host.fingerprint, how), accept_secure(b, &host, how));
        let (_, seen) = server.unwrap_or_else(|e| panic!("{how:?} server: {e}"));
        let client = client.unwrap_or_else(|e| panic!("{how:?} client: {e}"));
        assert_eq!(seen, device.fingerprint);
        assert_eq!(client.get_ref().1.protocol_version(), Some(rustls::ProtocolVersion::TLSv1_3));
    }
}

#[tokio::test]
async fn rust_dials_a_node_host_pinned_both_ways() {
    let dir = tempfile::tempdir().unwrap();
    let (host_dir, host) = ts_identity(&dir, "host").await;
    let (_, device) = ts_identity(&dir, "device").await;
    let mut node = Node::spawn(&["server", host_dir.to_str().unwrap(), &device.fingerprint]);
    let port = node.next().await["port"].as_u64().unwrap() as u16;

    let tcp = TcpStream::connect(("127.0.0.1", port)).await.unwrap();
    let tls = connect_secure(tcp, &device, &host.fingerprint, SignatureCheck::Webpki).await.expect("handshake");
    assert_eq!(tls.get_ref().1.protocol_version(), Some(rustls::ProtocolVersion::TLSv1_3));
    let (mut sender, conn) = h2util::client_handshake(tls).await.unwrap();
    tokio::spawn(conn);

    // Larger than the default 64 KB window, so flow control is exercised.
    let (status, body) =
        h2util::request(&mut sender, Method::POST, "/echo?x=1", Bytes::from(vec![b'x'; 200_000])).await.unwrap();
    let said = body_json(&body);
    assert_eq!(status, 200);
    assert_eq!(said["server"], "node");
    assert_eq!(said["me"], host.fingerprint.as_str());
    assert_eq!(said["you"], device.fingerprint.as_str(), "the Node host saw the Rust device's pinned identity");
    assert_eq!(said["admission"], "trusted");
    assert_eq!(said["path"], "/echo?x=1");
    assert_eq!(said["bodyBytes"], 200_000);
}

/// Serves `/…` with a JSON echo, like the Node helper does.
async fn rust_echo_host(listener: TcpListener, me: Identity) {
    let (tcp, _) = listener.accept().await.unwrap();
    let (tls, peer) = accept_secure(tcp, &me, SignatureCheck::Webpki).await.expect("accept");
    let mut conn = h2util::server_handshake(tls).await.unwrap();
    while let Some(next) = conn.accept().await {
        let Ok((request, mut respond)) = next else { break };
        let (me_fp, peer) = (me.fingerprint.clone(), peer.clone());
        tokio::spawn(async move {
            let path = request.uri().path().to_owned();
            let body = read_all(&mut request.into_body()).await.unwrap_or_default();
            let text = serde_json::json!({ "server": "rust", "me": me_fp, "you": peer, "path": path, "bodyBytes": body.len() }).to_string();
            let mut out = respond.send_response(Response::builder().status(200).body(()).unwrap(), false).unwrap();
            let _ = send_all(&mut out, Bytes::from(text), true).await;
        });
    }
}

#[tokio::test]
async fn node_dials_a_rust_host_pinned_both_ways() {
    let dir = tempfile::tempdir().unwrap();
    let (_, host) = ts_identity(&dir, "host").await;
    let (device_dir, device) = ts_identity(&dir, "device").await;
    let host_fp = host.fingerprint.clone();
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port = listener.local_addr().unwrap().port().to_string();
    let server = tokio::spawn(rust_echo_host(listener, host));

    let mut node = Node::spawn(&["client", device_dir.to_str().unwrap(), &port, &host_fp, "/api/host"]);
    let said = node.next().await;
    assert_eq!(said["tls"], "TLSv1.3", "{said}");
    assert_eq!(said["alpn"], "h2");
    assert_eq!(said["res"]["status"], 200);
    let body: Value = serde_json::from_str(said["res"]["body"].as_str().unwrap()).unwrap();
    assert_eq!(body["server"], "rust");
    assert_eq!(body["you"], device.fingerprint.as_str(), "the Rust host saw the Node device's identity");
    assert_eq!(body["path"], "/api/host");
    assert_eq!(body["bodyBytes"], "hello from node".len());
    server.abort();
}

#[tokio::test]
async fn a_wrong_pin_fails_in_both_directions() {
    let dir = tempfile::tempdir().unwrap();
    let (host_dir, host) = ts_identity(&dir, "host").await;
    let (device_dir, device) = ts_identity(&dir, "device").await;
    let (_, stranger) = ts_identity(&dir, "stranger").await;

    // Rust dials Node expecting someone else.
    let mut node = Node::spawn(&["server", host_dir.to_str().unwrap(), &device.fingerprint]);
    let port = node.next().await["port"].as_u64().unwrap() as u16;
    let tcp = TcpStream::connect(("127.0.0.1", port)).await.unwrap();
    let err = connect_secure(tcp, &device, &stranger.fingerprint, SignatureCheck::Webpki)
        .await
        .expect_err("must not connect");
    assert!(err.to_string().contains("ApplicationVerificationFailure"), "{err}");

    // Node dials Rust expecting someone else.
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port = listener.local_addr().unwrap().port().to_string();
    let server = tokio::spawn(rust_echo_host(listener, host));
    let mut node = Node::spawn(&["client", device_dir.to_str().unwrap(), &port, &stranger.fingerprint, "/x"]);
    assert_eq!(node.next().await["error"], "PeerIdentityError");
    server.abort();
}

// ---- spike 3: GOAWAY with a reason -----------------------------------------------------

#[tokio::test]
async fn rust_reads_the_reason_a_node_host_refuses_it_with() {
    let dir = tempfile::tempdir().unwrap();
    let (host_dir, host) = ts_identity(&dir, "host").await;
    let (_, device) = ts_identity(&dir, "device").await;
    // The host trusts nobody we know: this device is refused.
    let mut node = Node::spawn(&["server", host_dir.to_str().unwrap(), "-", "not-paired"]);
    let port = node.next().await["port"].as_u64().unwrap() as u16;

    let tcp = TcpStream::connect(("127.0.0.1", port)).await.unwrap();
    let tls =
        connect_secure(tcp, &device, &host.fingerprint, SignatureCheck::Webpki).await.expect("TLS itself succeeds");
    let (tap, slot) = GoAwayTap::new(tls);
    let (mut sender, conn) = h2util::client_handshake(tap).await.unwrap();
    let conn = tokio::spawn(conn);

    let res = h2util::request(&mut sender, Method::GET, "/api/host", Bytes::new()).await;
    assert!(res.is_err(), "a refused session serves nothing");
    let ended = timeout(WAIT, conn).await.expect("the connection ends").unwrap();

    let seen = slot.get().expect("the tap saw a GOAWAY");
    assert_eq!(seen.code, goaway::REFUSED_STREAM);
    assert_eq!(seen.reason(), Some("not-paired"));
    // What h2 itself gives: the code, and the data only inside Display.
    let err = ended.expect_err("h2 reports the GOAWAY as an error");
    assert!(err.is_go_away() && err.is_remote());
    assert_eq!(err.reason(), Some(h2::Reason::REFUSED_STREAM));
    assert!(err.to_string().contains("not-paired"), "Display happens to carry it: {err}");
}

#[tokio::test]
async fn node_reads_the_reason_a_rust_host_refuses_it_with() {
    let dir = tempfile::tempdir().unwrap();
    let (_, host) = ts_identity(&dir, "host").await;
    let (device_dir, _) = ts_identity(&dir, "device").await;
    let host_fp = host.fingerprint.clone();
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port = listener.local_addr().unwrap().port().to_string();
    let server = tokio::spawn(async move {
        let (tcp, _) = listener.accept().await.unwrap();
        let (tls, _who) = accept_secure(tcp, &host, SignatureCheck::Webpki).await.expect("accept");
        goaway::refuse(tls, "remote-access-off").await
    });

    let mut node = Node::spawn(&["client", device_dir.to_str().unwrap(), &port, &host_fp, "/api/host"]);
    let said = node.next().await;
    assert_eq!(said["goaway"]["code"], 7, "{said}");
    assert_eq!(said["goaway"]["data"], "remote-access-off", "HostLink's goaway handler gets the reason");
    assert!(said["res"]["error"].is_string(), "the request did not succeed: {said}");
    let _ = timeout(WAIT, server).await;
}

// ---- spike 4: the reverse tunnel -------------------------------------------------------

/// Node device → Rust host. The device offers `POST /peer/reverse`; the host
/// answers 200 and dials TLS + HTTP/2 back through that one stream.
#[tokio::test]
async fn a_rust_host_dials_a_node_device_back_through_its_own_stream() {
    let dir = tempfile::tempdir().unwrap();
    let (_, host) = ts_identity(&dir, "host").await;
    let (device_dir, device) = ts_identity(&dir, "device").await;
    let (host_fp, device_fp) = (host.fingerprint.clone(), device.fingerprint.clone());
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port = listener.local_addr().unwrap().port().to_string();

    let through_tunnel = tokio::spawn(async move {
        let (tcp, _) = listener.accept().await.unwrap();
        let (tls, who) = accept_secure(tcp, &host, SignatureCheck::Webpki).await.expect("accept");
        let mut outer = h2util::server_handshake(tls).await.unwrap();
        let (request, mut respond) = outer.accept().await.expect("a stream").expect("ok");
        assert_eq!((request.method(), request.uri().path()), (&Method::POST, "/peer/reverse"));
        // The outer connection must keep running: it carries the tunnel.
        tokio::spawn(async move { while let Some(Ok(_)) = outer.accept().await {} });

        let send = respond.send_response(Response::builder().status(200).body(()).unwrap(), false).unwrap();
        let pipe = H2Pipe::new(send, request.into_body());
        let inner_tls = connect_secure(pipe, &host, &who, SignatureCheck::Webpki)
            .await
            .expect("TLS through the tunnel, pinned to the device");
        let (mut sender, conn) = h2util::client_handshake(inner_tls).await.unwrap();
        tokio::spawn(conn);
        let mut results = Vec::new();
        for size in [0usize, 70_000, 1_500_000] {
            results.push(
                h2util::request(&mut sender, Method::POST, "/from-the-host", Bytes::from(vec![b'y'; size]))
                    .await
                    .unwrap(),
            );
        }
        results
    });

    let mut node = Node::spawn(&["reverse-device", device_dir.to_str().unwrap(), &port, &host_fp]);
    assert_eq!(node.next().await["offered"], true);
    let results = timeout(WAIT, through_tunnel).await.expect("in time").unwrap();
    for ((status, body), size) in results.iter().zip([0usize, 70_000, 1_500_000]) {
        let said = body_json(body);
        assert_eq!(*status, 200);
        assert_eq!(said["server"], "node");
        assert_eq!(said["me"], device_fp.as_str());
        assert_eq!(said["you"], host_fp.as_str(), "the device saw the host's identity inside the tunnel");
        assert_eq!(said["bodyBytes"], size);
    }
}

/// Rust device → Node host. The Rust side offers the stream and then serves
/// TLS + HTTP/2 on it; the Node host dials through with its normal dialer.
#[tokio::test]
async fn a_node_host_dials_a_rust_device_back_through_its_own_stream() {
    let dir = tempfile::tempdir().unwrap();
    let (host_dir, host) = ts_identity(&dir, "host").await;
    let (_, device) = ts_identity(&dir, "device").await;
    let mut node = Node::spawn(&["server", host_dir.to_str().unwrap(), &device.fingerprint]);
    let port = node.next().await["port"].as_u64().unwrap() as u16;

    let tcp = TcpStream::connect(("127.0.0.1", port)).await.unwrap();
    let tls = connect_secure(tcp, &device, &host.fingerprint, SignatureCheck::Webpki).await.unwrap();
    let (sender, conn) = h2util::client_handshake(tls).await.unwrap();
    tokio::spawn(conn);

    let mut ready = sender.ready().await.unwrap();
    let offer = http::Request::builder().method(Method::POST).uri("https://eos-peer/peer/reverse").body(()).unwrap();
    let (response, send) = ready.send_request(offer, false).unwrap();
    let response = timeout(WAIT, response).await.expect("in time").unwrap();
    assert_eq!(response.status(), 200, "the host took the tunnel");

    let pipe = H2Pipe::new(send, response.into_body());
    let (inner_tls, who) =
        accept_secure(pipe, &device, SignatureCheck::Webpki).await.expect("the host's TLS arrives through the tunnel");
    assert_eq!(who, host.fingerprint, "and it is the host we pinned");
    let mut inner = h2util::server_handshake(inner_tls).await.unwrap();
    let served = tokio::spawn(async move {
        let (request, mut respond) = inner.accept().await.expect("a stream").expect("ok");
        let drive = tokio::spawn(async move { while let Some(Ok(_)) = inner.accept().await {} });
        let path = request.uri().path().to_owned();
        let body = read_all(&mut request.into_body()).await.unwrap();
        let mut out = respond.send_response(Response::builder().status(200).body(()).unwrap(), false).unwrap();
        send_all(&mut out, Bytes::from(format!("rust device got {} bytes on {path}", body.len())), true).await.unwrap();
        tokio::time::sleep(Duration::from_millis(300)).await;
        drive.abort();
    });

    let said = node.next().await;
    assert_eq!(said["reverse"]["status"], 200, "{said}");
    assert_eq!(said["reverse"]["body"], "rust device got 300000 bytes on /through-the-tunnel");
    let _ = served.await;
}
